<template>
  <!-- Port of XMCL Me.vue / MeProfilePanel / UserAccountSwitcher layout. -->
  <div class="xmcl-account-page" :class="{ 'pcl-account-page--classic': pcl }"><aside class="xmcl-account-nav"><div class="xmcl-account-avatar"><span v-if="activeAccount?.profile?.skin?.url" class="account-face" :style="skinFaceStyle(activeAccount.profile.skin.url)" aria-hidden="true"></span><q-icon v-else name="person" size="38px"/></div><strong>账户中心</strong><button v-for="item in sections" :key="item.id" :class="{active:section===item.id}" @click="section=item.id"><q-icon :name="item.icon"/>{{ item.label }}</button></aside><main class="xmcl-account-content"><template v-if="section==='profile'"><div class="xmcl-account-header"><div><div class="eyebrow">MY ACCOUNT</div><h4>账户与玩家资料</h4><p>管理登录状态、皮肤、披风和认证服务。</p></div><div class="row q-gutter-sm"><q-btn color="primary" label="添加 Microsoft 账户" :disable="busy" @click="openLogin('microsoft')"/><q-btn flat label="添加离线账户" :disable="busy" @click="openLogin('offline')"/><q-btn flat label="添加 Yggdrasil" :disable="busy" @click="openLogin('yggdrasil')"/><q-btn flat label="添加 UnifiedPass" :disable="busy" @click="openLogin('unified-pass')"/></div></div><AccountPanel :accounts="accounts" :busy="busy" :execute="execute" @changed="onChanged"/></template><template v-else-if="section==='presets'"><div class="xmcl-account-header"><div><div class="eyebrow">AUTHORITY</div><h4>Yggdrasil 服务</h4><p>管理自定义认证服务器预设。</p></div><q-btn color="primary" label="添加服务" @click="addPreset"/></div><q-list bordered separator class="xmcl-preset-list"><q-item v-for="preset in presets" :key="preset.name"><q-item-section><q-item-label>{{ preset.name }} <q-badge v-if="preset.builtin">内置</q-badge><q-badge v-if="preset.managedLocal" color="positive">本地服务</q-badge></q-item-label><q-item-label caption>{{ preset.managedLocal ? '由 Luna 管理，登录时自动启动本地验证服务' : `${preset.authUrl} · ${preset.sessionUrl}` }}</q-item-label></q-item-section><q-item-section side><q-btn v-if="!preset.builtin" flat label="编辑" :disable="busy" @click="editPreset(preset)"/><q-btn v-if="!preset.builtin" flat color="negative" label="删除" :disable="busy" @click="removePreset(preset)"/></q-item-section></q-item><q-item v-if="!presets.length"><q-item-section class="text-grey-5">没有自定义认证服务。</q-item-section></q-item></q-list></template><template v-else><div class="xmcl-account-header"><div><div class="eyebrow">ACCOUNT TOOLS</div><h4>账户操作</h4><p>批量刷新账户并查看认证状态。</p></div></div><div class="row q-gutter-sm"><q-btn color="primary" label="刷新所有账户" :disable="busy" @click="refreshAll"/><q-btn outline label="安装认证组件" :disable="busy" @click="installAuthlib"/><q-btn flat label="检查认证客户端" :disable="busy" @click="checkAuthlib"/></div><div v-if="helper" class="text-caption text-grey-5 q-mt-sm">认证组件：{{ helper.installed ? `已安装 ${helper.version||''}` : '未安装' }}<span v-if="helper.path"> · {{ helper.path }}</span></div><q-list bordered separator class="q-mt-lg"><q-item v-for="a in accounts" :key="a.internalId || a.id"><q-item-section>{{ a.profileName || a.displayName }}</q-item-section><q-item-section side>{{ a.stateName || '未检查' }}</q-item-section></q-item></q-list></template><q-banner v-if="error" class="bg-red-9 q-mt-md">{{ error }}</q-banner></main><q-dialog v-model="loginShown" persistent><q-card class="login-card text-white"><q-card-section><div class="eyebrow">ACCOUNT LOGIN</div><div class="text-h6">{{ loginTitle }}</div><p class="text-caption text-grey-5">认证信息只会交给启动器后端，不会写入界面日志。</p></q-card-section><q-card-section><q-input v-if="loginType==='yggdrasil' || loginType==='unified-pass'" v-model="loginForm.username" dark outlined label="用户名" autofocus class="q-mb-md"/><q-input v-if="loginType==='offline'" v-model="loginForm.username" dark outlined label="离线玩家名"/><template v-if="loginType==='yggdrasil'"><q-select v-model="loginForm.presetName" dark outlined :options="presets" option-label="name" option-value="name" emit-value map-options label="认证服务" class="q-mb-md" @update:model-value="applyPreset"/><q-input v-model="loginForm.password" dark outlined type="password" label="密码" class="q-mb-md"/><q-input v-if="!loginForm.managedLocal" v-model="loginForm.authUrl" dark outlined label="认证 URL" class="q-mb-md"/><q-input v-if="!loginForm.managedLocal" v-model="loginForm.sessionUrl" dark outlined label="会话 URL"/></template><template v-if="loginType==='unified-pass'"><q-input v-model="loginForm.password" dark outlined type="password" label="密码" class="q-mb-md"/><q-input v-model="loginForm.serverId" dark outlined label="Server ID" class="q-mb-md"/><q-input v-model="loginForm.baseUrl" dark outlined label="API Base URL（可选）"/></template><q-banner v-if="loginType==='microsoft'" class="bg-blue-grey-9">点击继续后会弹出微软设备登录窗口。</q-banner></q-card-section><q-card-actions align="right"><q-btn flat label="取消" @click="loginShown=false"/><q-btn color="primary" label="继续" :loading="busy" @click="submitLogin"/></q-card-actions></q-card></q-dialog>
<q-dialog v-model="presetShown"><q-card class="login-card text-white"><q-card-section><div class="eyebrow">AUTHORITY</div><div class="text-h6">{{ presetEditing ? '编辑认证服务' : '添加认证服务' }}</div></q-card-section><q-card-section><q-input v-model="presetForm.name" dark outlined label="服务名称" class="q-mb-md"/><q-input v-model="presetForm.authUrl" dark outlined label="认证 URL" class="q-mb-md"/><q-input v-model="presetForm.sessionUrl" dark outlined label="会话 URL" class="q-mb-md"/><q-select v-model="presetForm.tokenType" dark outlined :options="['Standard','OAuth']" label="令牌类型" /></q-card-section><q-card-actions align="right"><q-btn flat label="取消" @click="presetShown=false"/><q-btn color="primary" label="保存" :disable="!presetForm.name || !presetForm.authUrl || !presetForm.sessionUrl" @click="savePreset"/></q-card-actions></q-card></q-dialog></div>
</template>
<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import AccountPanel from '../components/AccountPanel.vue';
const props=defineProps<{accounts:any[];busy:boolean;execute:(op:string,p?:Record<string,unknown>)=>Promise<any>;pcl?:boolean}>();const emit=defineEmits<{changed:[]}>();const section=ref('profile'),presets=ref<any[]>([]),helper=ref<any>(null),error=ref('');const activeAccount=computed(()=>props.accounts.find((account:any)=>account.default)||props.accounts[0]);
function skinFaceStyle(url:string){return {backgroundImage:`url(\"${String(url).replace(/\"/g,'%22')}\")`};}const sections=[{id:'profile',label:'账户和皮肤',icon:'person'},{id:'presets',label:'认证服务',icon:'dns'},{id:'tools',label:'账户工具',icon:'build'}];
const loginShown=ref(false),loginType=ref('offline'),loginForm=ref<any>({username:'',password:'',authUrl:'',sessionUrl:'',serverId:'',baseUrl:'',presetName:'',managedLocal:false,sourceName:'',tokenType:'Standard',authenticateEndpoint:'',refreshEndpoint:'',validateEndpoint:'',profileEndpoint:'',oauthTokenEndpoint:''});const presetShown=ref(false),presetEditing=ref<any>(null),presetForm=ref<any>({name:'',authUrl:'',sessionUrl:'',tokenType:'Standard'});const loginTitle=computed(()=>({microsoft:'登录 Microsoft 账户',offline:'添加离线账户',yggdrasil:'登录 Yggdrasil 账户','unified-pass':'登录 UnifiedPass'} as any)[loginType.value]||'登录账户');
function applyPreset(name:string){const preset=presets.value.find((p:any)=>p.name===name);if(!preset)return;Object.assign(loginForm.value,{authUrl:preset.authUrl||'',sessionUrl:preset.sessionUrl||'',sourceName:preset.sourceName||preset.name||'',tokenType:preset.tokenType||'Standard',managedLocal:Boolean(preset.managedLocal),authenticateEndpoint:preset.authenticateEndpoint||'',refreshEndpoint:preset.refreshEndpoint||'',validateEndpoint:preset.validateEndpoint||'',profileEndpoint:preset.profileEndpoint||'',oauthTokenEndpoint:preset.oauthTokenEndpoint||''});}
function openLogin(type:string){const preset=presets.value.find((p:any)=>!p.builtin)||presets.value[0];loginType.value=type;loginForm.value={username:'',password:'',authUrl:'',sessionUrl:'',serverId:'',baseUrl:'',presetName:preset?.name||'',managedLocal:false,sourceName:'',tokenType:'Standard',authenticateEndpoint:'',refreshEndpoint:'',validateEndpoint:'',profileEndpoint:'',oauthTokenEndpoint:''};if(type==='yggdrasil'&&preset)applyPreset(preset.name);loginShown.value=true;}
async function submitLogin(){try{const p:any={type:loginType.value};if(loginType.value==='microsoft'){}else if(loginType.value==='yggdrasil'){const {presetName,...form}=loginForm.value;Object.assign(p,form);}else Object.assign(p,loginForm.value);await props.execute('account.login',p);loginShown.value=false;emit('changed');}catch(e){error.value=String(e);}}
function onChanged(){emit('changed');}
function accountRef(account:any){return String(account?.internalId || account?.id || account?.profileName || '');}
async function loadPresets(){try{const r=await props.execute('account.preset.list');presets.value=Array.isArray(r)?r:[];}catch(e){error.value=String(e);}}
async function refreshAll(){for(const account of props.accounts)try{await props.execute('account.refresh',{account:accountRef(account)});}catch(e){error.value=String(e);}emit('changed');}
function editPreset(p:any){presetEditing.value=p;presetForm.value={name:p.name||'',authUrl:p.authUrl||'',sessionUrl:p.sessionUrl||'',tokenType:p.tokenType||'Standard'};presetShown.value=true;}
function addPreset(){presetEditing.value=null;presetForm.value={name:'',authUrl:'',sessionUrl:'',tokenType:'Standard'};presetShown.value=true;}
async function savePreset(){try{const p:any={...presetForm.value};if(presetEditing.value){await props.execute('account.preset.edit',{originalName:presetEditing.value.name,...p,authenticateEndpoint:presetEditing.value.authenticateEndpoint,refreshEndpoint:presetEditing.value.refreshEndpoint,validateEndpoint:presetEditing.value.validateEndpoint,profileEndpoint:presetEditing.value.profileEndpoint,oauthTokenEndpoint:presetEditing.value.oauthTokenEndpoint});}else await props.execute('account.preset.add',p);presetShown.value=false;await loadPresets();}catch(e){error.value=String(e);}}
async function removePreset(p:any){try{await props.execute('account.preset.remove',{name:p.name,confirm:true});await loadPresets();}catch(e){error.value=String(e);}}
async function checkAuthlib(){try{helper.value=await props.execute('authentication.helper.status',{helper:'authlib-injector'});}catch(e){error.value=String(e);}}
async function installAuthlib(){try{await props.execute('authentication.helper.install',{helper:'authlib-injector'});await checkAuthlib();}catch(e){error.value=String(e);}}
onMounted(loadPresets);
</script>
<style scoped>.login-card{width:520px;max-width:94vw;background:rgba(31,31,40,.96)!important;border:1px solid rgba(255,255,255,.12);border-radius:20px}.login-card :deep(.q-btn){text-transform:none}.xmcl-account-page{display:flex;min-height:680px;max-width:1250px;margin:0 auto}.xmcl-account-nav{width:250px;min-width:250px;padding:30px 18px;display:flex;flex-direction:column;align-items:stretch;gap:5px;border-right:1px solid rgba(255,255,255,.1)}.xmcl-account-avatar{width:76px;height:76px;border-radius:24px;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#6366f1,#312e81);margin-bottom:14px;overflow:hidden}.xmcl-account-avatar .account-face{display:block;width:100%;height:100%;border-radius:inherit;background-repeat:no-repeat;background-size:800% 800%;background-position:14.2857% 14.2857%}.xmcl-account-nav strong{font-size:18px;margin-bottom:18px}.xmcl-account-nav button{display:flex;align-items:center;gap:10px;padding:12px;border:0;border-radius:10px;background:transparent;color:rgba(255,255,255,.65);text-align:left;cursor:pointer}.xmcl-account-nav button:hover,.xmcl-account-nav button.active{background:rgba(129,140,248,.2);color:#fff}.xmcl-account-content{flex:1;min-width:0;padding:30px}.xmcl-account-header{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:24px}.xmcl-account-header h4{margin:4px 0;font-size:26px}.xmcl-account-header p{margin:0;color:rgba(255,255,255,.55)}.eyebrow{font-size:11px;letter-spacing:.14em;color:#a5b4fc;font-weight:700}.xmcl-preset-list{max-width:900px}@media(max-width:800px){.xmcl-account-page{display:block}.xmcl-account-nav{width:auto;min-width:0;border-right:0;border-bottom:1px solid rgba(255,255,255,.1);flex-direction:row;align-items:center;overflow:auto}.xmcl-account-avatar,.xmcl-account-nav strong{display:none}.xmcl-account-content{padding:20px 12px}.xmcl-account-header{display:block}.xmcl-account-header .row{margin-top:14px}}
.pcl-account-page--classic{color:#31485d;background:#f7f9fc}.pcl-account-page--classic .xmcl-account-nav{border-color:#dce4ec;background:#f7f9fc}.pcl-account-page--classic .xmcl-account-avatar{background:linear-gradient(135deg,#559bd0,#2f6eaa);border-radius:12px}.pcl-account-page--classic .xmcl-account-nav strong{color:#31577b}.pcl-account-page--classic .xmcl-account-nav button{color:#607488;border-radius:6px}.pcl-account-page--classic .xmcl-account-nav button:hover,.pcl-account-page--classic .xmcl-account-nav button.active{background:#dcecf8;color:#236a9f}.pcl-account-page--classic .xmcl-account-content{background:#f7f9fc}.pcl-account-page--classic .xmcl-account-header h4{color:#2f5979}.pcl-account-page--classic .xmcl-account-header p{color:#81909d}.pcl-account-page--classic .eyebrow{color:#4284b2}.pcl-account-page--classic .login-card{background:#fff!important;color:#31485d!important;border:1px solid #d5e0e8}.pcl-account-page--classic .login-card :deep(.text-grey-5){color:#81909d!important}.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__control){background:#fff}.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__native),.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__label),.pcl-account-page--classic .login-card :deep(.q-icon){color:#49677e}.pcl-account-page--classic .login-card :deep(.q-field--dark .q-field__control:before){border-color:#b9c9d6}.pcl-account-page--classic .login-card :deep(.bg-blue-grey-9){background:#f2f8fc!important;color:#698296}.pcl-account-page--classic .xmcl-preset-list{border-color:#d5e0e8}.pcl-account-page--classic .xmcl-preset-list :deep(.q-item__label){color:#49677e}.pcl-account-page--classic .xmcl-preset-list :deep(.q-item__label--caption){color:#81909d}.pcl-account-page--classic .text-grey-5{color:#81909d!important}@media(max-width:800px){.pcl-account-page--classic .xmcl-account-nav{background:#f7f9fc}}</style>
